import threading

def reproduce(connect, service) -> str | None:
    # Inspect fresh state to pick an amount that is individually allowed
    # (<= combined) but twice it exceeds the combined balance.
    with connect() as conn:
        rows = conn.execute(
            "SELECT id, household, balance FROM accounts ORDER BY household, id"
        ).fetchall()

    from collections import defaultdict
    households = defaultdict(list)
    combined = {}
    for acct_id, hh, bal in rows:
        households[hh].append(acct_id)
        combined[hh] = combined.get(hh, 0) + bal

    # Use up to 8 households, 2 accounts each
    targets = []  # (household, account_id, amount)
    for hh in sorted(households)[:8]:
        accts = households[hh][:2]
        if len(accts) < 2:
            continue
        total = combined[hh]
        if total < 2:
            continue
        amount = total // 2 + 1  # each alone passes: amount <= total (for total>=2), two together overdraw
        if amount > total:
            continue
        for acct in accts:
            targets.append((hh, acct, amount))

    if not targets:
        return None

    barrier = threading.Barrier(len(targets))
    errors = []

    def worker(acct_id, amount):
        try:
            with connect() as conn:
                barrier.wait(timeout=10)
                try:
                    service.withdraw(conn, acct_id, amount)
                except Exception as e:
                    # Expected: InsufficientFunds for the loser in a correct impl
                    errors.append(e)
        except Exception as e:
            errors.append(e)

    threads = [
        threading.Thread(target=worker, args=(acct, amount))
        for (_hh, acct, amount) in targets
    ]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=20)

    # Check money rule: no household combined balance may be < 0
    with connect() as conn:
        rows = conn.execute(
            "SELECT household, SUM(balance) FROM accounts GROUP BY household ORDER BY household"
        ).fetchall()
    for hh, total in rows:
        if total is not None and total < 0:
            return f"household {hh} overdrawn: combined balance {total} after concurrent partner withdrawals"
    return None
